float glyph(int n, vec2 p) {
    // p in [-1,1]; a 5x5 bitmap packed row by row, bit = x + 5*y.
    vec2 q = floor(p * vec2(-2.5, 2.5) + 2.5);
    if (q.x < 0.0 || q.y < 0.0 || q.x > 4.0 || q.y > 4.0) return 0.0;
    int a = int(q.x) + 5 * int(q.y);
    return float((n >> a) & 1);
}
void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    float cell = max(U.p0.x, 4.0);
    vec2 centre = (floor(fragCoord / cell) + 0.5) * cell;
    vec3 src = texture(iChannel0, centre / iResolution.xy).rgb;
    float l = pow(dot(src, vec3(0.2126, 0.7152, 0.0722)), U.p0.z);
    int n = 4;
    if (l > 0.10) n = 131200;
    if (l > 0.20) n = 14336;
    if (l > 0.30) n = 145536;
    if (l > 0.40) n = 1016800;
    if (l > 0.50) n = 18157905;
    if (l > 0.60) n = 27070835;
    if (l > 0.70) n = 11512810;
    if (l > 0.80) n = 15455950;
    vec2 local = (fragCoord - centre) / (cell * 0.5);
    float on = glyph(n, local * 1.1);
    vec3 tint = mix(vec3(0.25, 1.0, 0.45), src * 1.4, U.p0.y);
    fragColor = vec4(tint * on, 1.0);
}
